function validate([s1, s2, baseStr]) {
  if (s1.length < 1 || s1.length > 1000) return 's1 needs 1 to 1000 letters.';
  if (s2.length !== s1.length) return 's1 and s2 must have the same length.';
  if (baseStr.length < 1 || baseStr.length > 1000) return 'baseStr needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(s1 + s2 + baseStr)) return 'Use lowercase English letters only.';
  return null;
}

