function smallestEquivalentString(s1, s2, baseStr) {
  const parent = Array.from({ length: 26 }, (_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  for (let i = 0; i < s1.length; i++) {
    const rootA = find(s1.charCodeAt(i) - 97);
    const rootB = find(s2.charCodeAt(i) - 97);
    if (rootA < rootB) {
      parent[rootB] = rootA;
    } else {
      parent[rootA] = rootB;
    }
  }
  let result = '';
  for (const ch of baseStr) {
    const root = find(ch.charCodeAt(0) - 97);
    result += String.fromCharCode(root + 97);
  }
  return result;
}

