function smallestEquivalentString(s1, s2, baseStr) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const same = letters.split('').map(a => letters.split('').map(b => a === b));
  for (let i = 0; i < s1.length; i++) {
    const a = letters.indexOf(s1[i]), b = letters.indexOf(s2[i]);
    same[a][b] = same[b][a] = true;
  }
  // Floyd-Warshall style transitive closure.
  for (let k = 0; k < 26; k++)
    for (let a = 0; a < 26; a++)
      for (let b = 0; b < 26; b++)
        if (same[a][k] && same[k][b]) same[a][b] = true;
  return baseStr.split('').map(ch => {
    const a = letters.indexOf(ch);
    for (let b = 0; b < 26; b++) if (same[a][b]) return letters[b];
    return ch;
  }).join('');
}

