function generate(rand, size) {
  const large = size === 'large';
  const alphabet = large ? 26 : 2 + Math.floor(rand() * 8);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const n = large ? 1000 : 1 + Math.floor(rand() * 6);
  const m = large ? 1000 : 1 + Math.floor(rand() * 8);
  let s1 = '', s2 = '', baseStr = '';
  // Large inputs keep few distinct pairs so several groups survive.
  const pairs = Array.from({ length: large ? 12 : n }, () => [letter(), letter()]);
  for (let i = 0; i < n; i++) {
    const [a, b] = pairs[Math.floor(rand() * pairs.length)];
    s1 += a;
    s2 += b;
  }
  for (let i = 0; i < m; i++) baseStr += letter();
  return [s1, s2, baseStr];
}
